-- Seed 100 sample Rishmora products, product details, highlights, and 15-20 demo reviews each.
-- Run schema.sql and product_content_tables.sql first.
-- Reviews are explicitly marked DEMO so they are not mistaken for real customer feedback.
-- Re-running this query does not duplicate products or add demo reviews to products
-- that already have reviews. Replace demo review rows with genuine customer feedback before launch.

DO $seed$
BEGIN
CREATE TEMP TABLE IF NOT EXISTS rishmora_seed_products (
    seed_no integer PRIMARY KEY,
    name text NOT NULL,
    category text NOT NULL,
    price numeric(12,2) NOT NULL,
    description text NOT NULL,
    detail varchar(15000) NOT NULL,
    highlight_1 varchar(500) NOT NULL,
    highlight_2 varchar(500) NOT NULL,
    highlight_3 varchar(500) NOT NULL
);

TRUNCATE rishmora_seed_products;


SELECT s.name, s.price, s.description
FROM rishmora_seed_products AS s
WHERE NOT EXISTS (SELECT 1 FROM product AS p WHERE p.name = s.name);

SELECT s.detail, p.product_id
FROM rishmora_seed_products AS s
JOIN product AS p ON p.name = s.name
ON CONFLICT (prid) DO UPDATE SET detail = EXCLUDED.detail;

SELECT p.product_id, h.highlight, h.display_order
FROM rishmora_seed_products AS s
JOIN product AS p ON p.name = s.name
CROSS JOIN LATERAL (VALUES
    (1::smallint, left(s.highlight_1, length(s.highlight_1) - 5)),
    (2::smallint, left(s.highlight_2, length(s.highlight_2) - 5)),
    (3::smallint, left(s.highlight_3, length(s.highlight_3) - 5))
) AS h(display_order, highlight)
ON CONFLICT (prid, display_order) DO UPDATE SET highlight = EXCLUDED.highlight;

SELECT p.product_id,
       'demo-seed-' || lpad(s.seed_no::text, 3, '0') || '-' || lpad(g.review_no::text, 2, '0'),
       CASE WHEN g.review_no % 9 = 0 THEN 3
            WHEN g.review_no % 4 = 0 THEN 4
            ELSE 5 END,
       'DEMO REVIEW #' || lpad(g.review_no::text, 2, '0'),
       'DEMO DATA ONLY: Sample review for ' || s.name ||
       '. This is placeholder content for layout testing, not feedback from a real customer. Replace it before launch.',
       now() - (g.review_no::text || ' days')::interval
FROM rishmora_seed_products AS s
JOIN product AS p ON p.name = s.name
CROSS JOIN LATERAL generate_series(1, 15 + (s.seed_no % 6)) AS g(review_no)
WHERE NOT EXISTS (SELECT 1 FROM reviews AS existing WHERE existing.prid = p.product_id);

DROP TABLE rishmora_seed_products;

END;
$seed$;

